export const ancientScienceData=[{id:"zero",title:"Zero & Decimal System",category:"Mathematics",period:"c. 5th Century CE",image:"assets/zero.svg",contributor:"Brahmagupta, Aryabhata",summary:"The concept of zero as a number and the decimal place-value system transformed mathematics, enabling modern arithmetic, algebra, calculus, and computing systems.",significance:"Foundation of positional notation and modern mathematics worldwide.",link:"../decimal-number-system-explorer/index.html"},{id:"aryabhata",title:"Earth's Rotation & Astronomy",category:"Astronomy",period:"499 CE",image:"assets/aryabhata.jpg",contributor:"Aryabhata",summary:"Aryabhata correctly proposed that the Earth rotates on its axis and that the apparent movement of the stars is a relative motion. He also provided accurate calculations for solar and lunar eclipses.",significance:"Pioneered early heliocentric concepts and scientific explanation of eclipses."},{id:"ayurveda",title:"Ayurveda & Surgery",category:"Medicine",period:"c. 600 BCE",image:"assets/sushruta.jpg",contributor:"Sushruta, Charaka",summary:"Sushruta Samhita details advanced surgical procedures, including rhinoplasty (plastic surgery) and cataract surgery. Charaka Samhita laid the foundations for internal medicine and holistic healthcare.",significance:"One of the world's oldest medical systems with pioneering surgical techniques."},{id:"iron-pillar",title:"Metallurgy & Zinc Extraction",category:"Metallurgy",period:"c. 400 CE",image:"assets/iron-pillar.jpg",contributor:"Ancient Metallurgists",summary:"The Iron Pillar of Delhi is a testament to the high level of skill achieved by ancient Indian ironsmiths in the extraction and processing of iron, remaining rust-resistant for over 1600 years. India also pioneered the difficult distillation process for extracting Zinc.",significance:"Advanced rust-resistant iron and world's first zinc extraction at Zawar."},{id:"trigonometry",title:"Trigonometric Functions",category:"Mathematics",period:"5th-15th Century CE",image:"assets/trigonometry.jpg",contributor:"Aryabhata, Madhava",summary:"Indian mathematicians developed the sine (jya) and cosine (koti-jya) functions. The Kerala School of Astronomy and Mathematics, led by Madhava, discovered infinite series for trigonometric functions centuries before Newton and Leibniz.",significance:"Laid the groundwork for modern calculus and mathematical analysis."},{id:"architecture",title:"Urban Planning & Water Management",category:"Engineering",period:"c. 2500 BCE",image:"assets/architecture.jpg",contributor:"Indus Valley Civilization",summary:"Cities like Mohenjo-Daro and Dholavira featured highly advanced urban planning, standardized baked bricks, and sophisticated drainage and water management systems unmatched in the ancient world.",significance:"Earliest known examples of comprehensive urban sanitation systems."}];